SourceCode.Declaration:
/// <summary>
/// Retryable SysOperation service that reindexes <c>ConDemoNoteHeader</c> records.
/// The work is idempotent, so the batch framework may safely re-run it after a transient fault.
/// </summary>
class ConDemoNoteReindexService extends SysOperationServiceBase implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Iterates the demo note headers and reindexes them.
/// </summary>
/// <param name = "_contract">The data contract holding the operation parameters.</param>
public void process(ConDemoNoteReindexContract _contract)
{
    ConDemoNoteHeader   demoNoteHeader;
    BatchGroupId        batchGroupId;
    Counter             processed;

    batchGroupId = _contract.parmBatchGroupId();

    while select NoteId, Subject from demoNoteHeader
    {
        processed++;
    }

    info(strFmt('%1 %2 (%3)', "@DMF:NumberOfRecordsProcessed", processed, batchGroupId));
}

/// <summary>
/// Opts the task into automatic retry on transient faults.
/// </summary>
/// <returns>Always true - the operation is idempotent.</returns>
public boolean isRetryable()
{
    return true;
}
